import java.util.*;import java.util.jar.*;public class ProtocolSemanticCheck {public static void main(String[] a)throws Exception{int count=0;try(var l=new JarFile(a[0]);var r=new JarFile(a[1])){for(var e:l.stream().filter(x->x.getName().startsWith(a[2])&&x.getName().endsWith(".class")).toList()){var re=r.getJarEntry(e.getName());if(re==null)throw new AssertionError("Missing "+e.getName());var n=OpeningDelta.read(l.getInputStream(e).readAllBytes(),0);var o=OpeningDelta.read(r.getInputStream(re).readAllBytes(),0);boolean same=n.name.equals(o.name)&&Objects.equals(n.superName,o.superName)&&n.access==o.access&&n.interfaces.equals(o.interfaces)&&n.fields.size()==o.fields.size()&&n.methods.size()==o.methods.size();for(var f:n.fields){var old=o.fields.stream().filter(x->x.name.equals(f.name)).findFirst().orElse(null);same&=old!=null&&old.desc.equals(f.desc)&&old.access==f.access&&Objects.equals(old.value,f.value);}for(var m:n.methods){var old=o.methods.stream().filter(x->OpeningDelta.key(x).equals(OpeningDelta.key(m))).findFirst().orElse(null);same&=OpeningDelta.eq(old,m);}if(!same)throw new AssertionError("Semantic mismatch "+e.getName());count++;}}if(count==0)throw new AssertionError("Empty prefix");System.out.println("PASS "+count+" protocol classes semantically identical");}}